import{_ as l,o,c as a,a2 as r}from"./chunks/framework.C4u7U0Dw.js";const g=JSON.parse('{"title":"第 5 章 加载一个真正用得上的 Skill（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第5章 加载一个真正用得上的 Skill（易懂版）.md","filePath":"easy/第5章 加载一个真正用得上的 Skill（易懂版）.md"}'),i={name:"easy/第5章 加载一个真正用得上的 Skill（易懂版）.md"};function e(s,t,n,d,h,u){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="第-5-章-加载一个真正用得上的-skill-易懂版" tabindex="-1">第 5 章 加载一个真正用得上的 Skill（易懂版） <a class="header-anchor" href="#第-5-章-加载一个真正用得上的-skill-易懂版" aria-label="Permalink to &quot;第 5 章 加载一个真正用得上的 Skill（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 5 章 加载一个真正用得上的 Skill（完整版）](../../bluebook/第一篇 使用手册：先把我用起来/第 5 章 加载一个真正用得上的 Skill.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>Skill 就是把一套&quot;干活方法&quot;打包成按钮——以后说一句话，我就按标准流程干活。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>你点外卖时选&quot;<strong>再来一单</strong>&quot;——不用重新挑菜、填地址，一键重复上次的完美订单。</p><p>Skill 就是这个：<strong>把&quot;怎么做这件事&quot;的整套经验打包</strong>，你下次直接&quot;再来一单&quot;。</p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>Skill = 经验包</strong>：里面装着&quot;做这件事的步骤、模板、注意事项&quot;，是别人（或你自己）总结好的方法论。</li><li><strong>一句话加载</strong>：跟我说&quot;用 xx Skill&quot;，我就按里面的标准流程走，不用你现场一步步教。</li><li><strong>装上就能用</strong>：加载后，普通任务立刻升级成&quot;专家级流程&quot;。</li></ol><h2 id="一个-skill-里有什么" tabindex="-1">一个 Skill 里有什么？ <a class="header-anchor" href="#一个-skill-里有什么" aria-label="Permalink to &quot;一个 Skill 里有什么？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>零件</th><th>干嘛用</th></tr></thead><tbody><tr><td><strong>说明</strong></td><td>这 Skill 是干嘛的、什么时候用</td></tr><tr><td><strong>步骤</strong></td><td>先做什么、再做什么、最后做什么</td></tr><tr><td><strong>模板</strong></td><td>现成的格式，直接套</td></tr><tr><td><strong>检查点</strong></td><td>做完怎么验、常见坑在哪</td></tr></tbody></table><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;用「周报」Skill 把我的本周工作生成一份周报。&quot;</p><p><strong>你会看到</strong>：我不再瞎写，而是按 Skill 的模板走：收集本周产出 → 按&quot;成果/问题/计划&quot;三段填 → 检查格式 → 交付。</p></blockquote><h2 id="怎么挑到好-skill" tabindex="-1">怎么挑到好 Skill？ <a class="header-anchor" href="#怎么挑到好-skill" aria-label="Permalink to &quot;怎么挑到好 Skill？&quot;">​</a></h2><ul><li>✅ 看<strong>适用场景</strong>：是不是正好解决你现在的问题；</li><li>✅ 看<strong>说明清晰</strong>：写的用途和你理解一致；</li><li>✅ 看<strong>来源可靠</strong>：官方、社区口碑好、或者你自己写的最懂你；</li><li>✅ <strong>先小试一把</strong>：用个低风险任务试跑，好用再长期用。</li></ul><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 装了不用——Skill 的价值在&quot;用了&quot;才有；</li><li>❌ 盲目信 Skill——它只是方法论，<strong>结果照样要检查</strong>；</li><li>❌ 到处装一堆——<strong>先装 1-2 个最常碰的场景</strong>，用熟了再扩展。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>Skill = 干活方法论打包成按钮。加载它，用标准流程完成任务。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>回想你重复做最多的一件事（周报？整理文件？）——<strong>它能不能打包成一个 Skill？</strong> 能的话，就去找一个装上试试。</p><p>👉 [下一章：记忆系统，让 AI 越来越懂你（易懂版）](第6章 记忆系统：让 AI 越来越懂你（易懂版）.md)</p>',22)])])}const q=l(i,[["render",e]]);export{g as __pageData,q as default};
